def fingerprint(raw):
    return hashlib.md5(raw.replace(b"\r\n", b"\n")).hexdigest()


def main():
    if os.path.basename(os.getcwd()) == "documentation":
        raise SystemExit("ERROR: run this from the GALLERY repo ROOT, next to "
                         "interactive.html -- not from documentation/. "
                         "NOTHING was written.")
    if not (os.path.isfile("interactive.html") and os.path.isfile("daily_run.py")):
        raise SystemExit("ERROR: interactive.html and daily_run.py are not "
                         "here, so this is not the gallery root. NOTHING was "
                         "written.")

    staged = []
    for path in sorted(BASE):
        with open(path, "rb") as handle:
            raw = handle.read()
        got = fingerprint(raw)
        if got != BASE[path]:
            raise SystemExit(
                "ERROR: %s is not the file this patch was built against\n"
                "       (expected %s, found %s). It has changed since\n"
                "       c48f9a92, or this patch has already run. NOTHING was\n"
                "       written." % (path, BASE[path], got))
        crlf = b"\r\n" in raw
        text = raw.decode("utf-8").replace("\r\n", "\n")
        done = []
        if path == "data/objects_config.json":
            text = NEW_CONFIG
            done.append("nine position_accuracy links, as the mirror writes them")
        else:
            for label, old, new in EDITS[path]:
                count = text.count(old)
                if count != 1:
                    raise SystemExit("ANCHOR FAIL (%s): expected 1 match in %s, "
                                     "found %d. NOTHING was written."
                                     % (label, path, count))
                text = text.replace(old, new)
                done.append(label)
        if any(ord(ch) > 127 for ch in text):
            raise SystemExit("ERROR: %s would hold non-ASCII text. NOTHING "
                             "was written." % path)
        staged.append((path, text, crlf, done))

    json.loads(NEW_CONFIG)
    for path, _content in NEW_FILES:
        if os.path.exists(path):
            raise SystemExit("ERROR: %s already exists, so this patch has "
                             "probably run. NOTHING was written." % path)

    for path, text, crlf, done in staged:
        data = text.replace("\n", "\r\n") if crlf else text
        with open(path, "wb") as handle:
            handle.write(data.encode("utf-8"))
        for label in done:
            print("ok  %-30s %s" % (path, label))
    for path, content in NEW_FILES:
        with open(path, "wb") as handle:
            handle.write(content.encode("utf-8"))
        print("ok  %-30s new" % path)

    print("")
    print("patch applied")
    print("")
    print("NEXT:")
    print("  1. python gallery_maintenance_run.py -- it pulls the orrery's new")
    print("     export first. Every gating checker should pass, including the")
    print("     new one, \"Solar System figures\", which prints each body's")
    print("     distance and what set its figures.")
    print("  2. Move this script into documentation/. Commit and push.")
    print("  3. python gallery_maintenance_run.py --live")
    print("  4. On your phone and desktop, open")
    print("     palomasorrery.com/interactive.html?exhibit=solar-system,")
    print("     tick Pluto, Neptune, Uranus, Jupiter and Apophis, and tap each.")
    print("     Pluto, Neptune and Uranus should end in 0,000 km; Apophis")
    print("     should have the extra line.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
